@startuml

class User {
  + id : string
  + name : string
  + address : string
  + birthday : date
}

class BusinessOwner extends User {
  + linkedin_account : string
}

class HungryCustomer extends User {
  + delivery_address : string
}

class Entertainer extends User {
  + stage_name : string
  + bio : string
  + price_per_30_minutes : double
}

class PizzaRestaurant {
  + zip_code : string
  + address : string
  + phone_number : string
  + website : string
  + opening_hours : string
}

class Pizza {
  + name : string
  + crust_structure : string
  + price : double
}

class Order {
  + id : string
  + date_time : datetime
  + latest_delivery_time : time
  + number_of_people : int
}

class EntertainmentOrder extends Order {
  + entertainment_type : string
  + duration : int
}

class EntertainerAvailability {
  + day : string
}

BusinessOwner "1" -- "0..*" PizzaRestaurant : owns
PizzaRestaurant "1" -- "1..*" Pizza : offers
PizzaRestaurant "1" -- "0..*" Order : receives
HungryCustomer "1" -- "0..*" Order : makes
Order "1" -- "1..*" Pizza : contains
EntertainmentOrder "0..*" -- "1" Entertainer : fulfilled by
Entertainer "1" -- "0..*" EntertainerAvailability : has
Entertainer "0..*" -- "0..*" PizzaRestaurant : works with
EntertainerAvailability "0..*" -- "1" PizzaRestaurant : for

@enduml

